import React, { useState, useEffect } from 'react';
import { Modal, ModalHeader, ModalBody, ModalFooter, Row, Col } from 'reactstrap';
import validator from 'validator';
import CustomInput from 'views/admin/Common/CustomInput';
import CustomSelect from 'components/CustomSelect';
import CustomButton from 'components/CustomButton';
import { regNoStatic, courseStatic } from 'config/constants';
import colors from 'config/colors';
import { toLoginEmail } from 'utils/commonFunc';

// Mirrors QuickStudentRequest.Relation on the backend (spelling of GUARDIN included).
const RELATION_OPTIONS = ['FATHER', 'MOTHER', 'UNCLE', 'AUNTY', 'COUSIN', 'FRIEND', 'GUARDIN'].map(value => ({
  value,
  label: value.charAt(0) + value.slice(1).toLowerCase(),
}));

const emptyForm = {
  courseId: null,
  firstName: '',
  lastName: '',
  registerNumber: '',
  guardianName: '',
  relation: null,
  guardianEmail: '',
  guardianMobile: '',
};

// Limits follow QuickStudentRequest's bean validation so the message shows up next to the field
// instead of as a generic "Validation Failed" toast.
const validate = (data, askCourse) => {
  const errors = {};
  if (askCourse && !data.courseId) errors.courseId = `Select ${courseStatic.toLowerCase()}`;
  const firstName = data.firstName.trim();
  if (!firstName) errors.firstName = 'Enter first name';
  else if (firstName.length < 3) errors.firstName = 'First name needs at least 3 characters';
  if (!data.lastName.trim()) errors.lastName = 'Enter last name';
  // Optional in the request DTO, but the service reads it unconditionally, so it's required here.
  if (!data.registerNumber.trim()) errors.registerNumber = `Enter ${regNoStatic.toLowerCase()}`;
  const guardianName = data.guardianName.trim();
  if (!guardianName) errors.guardianName = 'Enter guardian name';
  else if (guardianName.length < 3) errors.guardianName = 'Guardian name needs at least 3 characters';
  if (!data.relation) errors.relation = 'Select relation';
  const email = toLoginEmail(data.guardianEmail);
  if (!email) errors.guardianEmail = 'Enter guardian email';
  else if (!validator.isEmail(email)) errors.guardianEmail = 'Invalid email';
  else if (email.length > 50) errors.guardianEmail = 'Email can be at most 50 characters';
  if (!data.guardianMobile.trim()) errors.guardianMobile = 'Enter guardian mobile number';
  return errors;
};

const required = text => (
  <>
    {text}
    <sup> *</sup>
  </>
);

// Opened from a class list the class is already known (className); opened from the batch list there is none,
// so askCourse adds a class picker (courseOptions) and the picked class is passed to onSave as its 2nd argument.
const QuickStudentFormModal = ({ isOpen, className, askCourse, courseOptions, saving, onClose, onSave }) => {
  const [data, setData] = useState(emptyForm);
  const [errors, setErrors] = useState({});

  useEffect(() => {
    if (isOpen) {
      setData(emptyForm);
      setErrors({});
    }
  }, [isOpen]);

  const handleChange = (name, value) => {
    setData(prev => ({ ...prev, [name]: value }));
    setErrors(prev => (prev[name] ? { ...prev, [name]: undefined } : prev));
  };

  const handleSubmit = e => {
    e.preventDefault();
    const nextErrors = validate(data, askCourse);
    setErrors(nextErrors);
    if (Object.keys(nextErrors).length) return;
    onSave(
      {
        firstName: data.firstName.trim(),
        lastName: data.lastName.trim(),
        registerNumber: data.registerNumber.trim(),
        guardianName: data.guardianName.trim(),
        relation: data.relation,
        guardianEmail: toLoginEmail(data.guardianEmail),
        guardianMobile: data.guardianMobile.trim(),
      },
      data.courseId
    );
  };

  return (
    <Modal size="lg" isOpen={isOpen} toggle={onClose} className="modal-offset-sidebar">
      <form onSubmit={handleSubmit}>
        <ModalHeader toggle={onClose}>QUICK ADD STUDENT</ModalHeader>
        <ModalBody>
          <div style={{ fontSize: 13, color: '#6b778a', marginBottom: 14 }}>
            {!askCourse && (
              <>
                Adding to {courseStatic}: <b>{className || '--'}</b>.{' '}
              </>
            )}
            The guardian email becomes the login username and the guardian mobile number is the initial password. Other
            details can be filled in later from the student profile.
          </div>
          {askCourse && (
            <div className="mb-3">
              <CustomSelect
                label={courseStatic}
                name="courseId"
                isRequired
                usePortal
                value={data.courseId}
                options={courseOptions}
                onChange={handleChange}
                error={errors.courseId}
              />
            </div>
          )}
          <div style={{ fontWeight: 'bold', fontSize: 13, color: colors.grey2, marginBottom: 6 }}>Student</div>
          <Row>
            <Col md={6}>
              <CustomInput
                label={required('First name')}
                name="firstName"
                value={data.firstName}
                onChange={handleChange}
                error={errors.firstName}
              />
            </Col>
            <Col md={6}>
              <CustomInput
                label={required('Last name')}
                name="lastName"
                value={data.lastName}
                onChange={handleChange}
                error={errors.lastName}
              />
            </Col>
            <Col md={6}>
              <CustomInput
                label={required(regNoStatic)}
                name="registerNumber"
                value={data.registerNumber}
                onChange={handleChange}
                error={errors.registerNumber}
              />
            </Col>
          </Row>
          <div style={{ fontWeight: 'bold', fontSize: 13, color: colors.grey2, margin: '6px 0' }}>Guardian</div>
          <Row>
            <Col md={6}>
              <CustomInput
                label={required('Name')}
                name="guardianName"
                value={data.guardianName}
                onChange={handleChange}
                error={errors.guardianName}
              />
            </Col>
            <Col md={6}>
              <div className="mb-3">
                <CustomSelect
                  label="Relation"
                  name="relation"
                  isRequired
                  usePortal
                  value={data.relation}
                  options={RELATION_OPTIONS}
                  onChange={handleChange}
                  error={errors.relation}
                />
              </div>
            </Col>
            <Col md={6}>
              <CustomInput
                label={required('Username or Email')}
                name="guardianEmail"
                value={data.guardianEmail}
                onChange={handleChange}
                error={errors.guardianEmail}
              />
            </Col>
            <Col md={6}>
              <CustomInput
                label={required('Mobile')}
                name="guardianMobile"
                value={data.guardianMobile}
                onChange={handleChange}
                error={errors.guardianMobile}
              />
            </Col>
          </Row>
        </ModalBody>
        <ModalFooter>
          <CustomButton
            className="mr-2"
            type="button"
            color="default"
            disabled={saving}
            onClick={onClose}
            name="Cancel"
          />
          <CustomButton
            type="submit"
            name="Add Student"
            disabled={saving}
            loading={saving}
            style={{ backgroundColor: colors.accent, color: colors.white }}
          />
        </ModalFooter>
      </form>
    </Modal>
  );
};

export default QuickStudentFormModal;
