import React, { useState, useEffect } from 'react';
import { Modal, ModalHeader, ModalBody, ModalFooter, Row, Col, Input, Label, FormGroup } from 'reactstrap';
import moment from 'moment';
import validator from 'validator';
import Select from 'react-select';
import DatePicker from 'react-datepicker';
import { languages } from '../../Guardian/components/GuardianFormModal';
import CustomCheckbox from '../../../../components/CustomCheckbox';
import CustomButton from '../../../../components/CustomButton';
import { formResMessage, getCurrentYearBatchUtils, toLoginEmail } from '../../../../utils/commonFunc';
import { courseStatic } from '../../../../config/constants';
import CustomSelect from 'components/CustomSelect';
// import { handleKeyNumberPress, handleKeyCharacterPress } from 'utils/commonFunc';

const StudentFormModal = ({
  isModalOpen,
  fetchBatchCourse,
  batchCourses,
  // fetchSchoolGuardians,
  guardians,
  saveStudent,
  updateStudent,
  studentUpdateSuccess,
  formModalCloseProp,
  student,
  scrollToTop,
  unMappedGuardianList,
}) => {
  const stateObj = {
    data: {
      courseId: 0,
      guardian: { guardianId: '' },
      studentId: 0,
      registerNumber: 0,
      category: 'General',
      firstName: '',
      // "middleName": "",
      lastName: '',
      email: '',
      gender: '',
      dateOfBirth: '',
      bloodGroup: '',
      birthPlace: '',
      joiningDateTime: moment(moment(new Date()).format('YYYY-MM-DD HH:mm:ss')).valueOf(),
      nationality: 'INDIA',
      motherTongue: 'EN',
      hostel: 'false',
    },
    errors: {},
    loading: false,
  };

  const courseArr =
    batchCourses &&
    batchCourses?.map(item => {
      return {
        courseId: item.courseId,
        label: `${item.name} (${item.code})`,
        value: item.courseId,
      };
    });

  const allGuardians = [...guardians, ...unMappedGuardianList];
  const guardianArr = allGuardians?.map(item => {
    return {
      guardianId: item.guardianId,
      label: `${item.name} (${item.email})`,
      value: item.guardianId,
    };
  });

  const [stateVal, setState] = useState(stateObj);

  useEffect(() => {
    if (student && Object.keys(student).length) {
      setState(prevState => ({
        ...prevState,
        data: {
          school: { schoolId: student?.schoolId || student?.currentCourse?.school?.schoolId },
          courseId: student?.courseId || student?.currentCourse?.courseId,
          studentId: student.studentId,
          registerNumber: student.registerNumber,
          status: student.status,
          category: student.category,
          firstName: student.firstName,
          lastName: student.lastName,
          email: student.email,
          gender: student.gender,
          dateOfBirth: student.dateOfBirth,
          bloodGroup: student.bloodGroup,
          birthPlace: student.birthPlace,
          joiningDateTime: student.joiningDateTime,
          nationality: student.nationality,
          motherTongue: student.motherTongue,
          hostel: student.hostel,
          guardian: { guardianId: student?.guardian?.guardianId || student?.guardianId },
        },
      }));
    }
  }, [isModalOpen, student]);

  const { batchId } = getCurrentYearBatchUtils();
  useEffect(() => {
    if (batchId) {
      fetchBatchCourse(batchId, 'FORM_MODAL');
    }
  }, [batchId, fetchBatchCourse]);

  const handleChange = e => {
    e.persist();
    setState(prevState => ({
      ...prevState,
      data: { ...prevState.data, [e.target.name]: e.target.value },
    }));
  };

  const handleCheckChange = e => {
    e.persist();
    setState(prevState => ({
      ...prevState,
      data: { ...prevState.data, [e.target.name]: e.target.id },
    }));
  };

  const handleSelectChange = (name, selectItem) => {
    setState(prevState => ({
      ...prevState,
      data: {
        ...prevState.data,
        [name]: name === 'guardian' ? { guardianId: selectItem } : selectItem,
      },
    }));
  };

  const handleSelectLanguageChange = (name, selectValue) => {
    setState(prevState => ({
      ...prevState,
      data: {
        ...prevState.data,
        [name]: selectValue,
      },
    }));
  };

  const handleDateChange = (name, date) => {
    setState(prevState => ({
      ...prevState,
      data: {
        ...prevState.data,
        [name]: moment(moment(date).format('YYYY-MM-DD HH:mm:ss')).valueOf(),
      },
    }));
  };

  const handleSubmit = e => {
    e.preventDefault();
    const { data } = stateVal;
    const errors = validate(data);
    setState(prevState => ({ ...prevState, errors }));
    if (!Object.keys(errors).length) {
      setState(prevState => ({ ...prevState, loading: true }));
      const payload = { ...data, email: toLoginEmail(data.email) };
      if (data.studentId) {
        return updateStudent(payload)
          .then(() => {
            stateValReset();
            studentUpdateSuccess('update');
          })
          .catch(err => {
            setError(err);
          });
      }
      return saveStudent(payload)
        .then(() => {
          stateValReset();
          studentUpdateSuccess('add');
        })
        .catch(err => setError(err));
    }
  };

  const setError = err => {
    scrollToTop();
    // window.scrollTo(0, 0);
    setState(prevState => ({
      ...prevState,
      errors: {
        global: formResMessage(err),
      },
      loading: false,
    }));
  };

  const stateValReset = () => {
    setState(stateObj);
  };

  const formModalClose = () => {
    stateValReset();
    formModalCloseProp();
  };

  const validate = data => {
    const errors = {};
    if (validator.isEmpty(String(data?.courseId || ''))) {
      errors.courseId = `${courseStatic} cannot be empty`;
    }
    if (data.guardian && validator.isEmpty(String(data?.guardian?.guardianId || ''))) {
      errors.guardianId = 'Guardian cannot be empty';
    }
    if (validator.isEmpty(String(data.category || ''))) {
      errors.category = 'Category cannot be empty';
    }
    if (validator.isEmpty(String(data.firstName || ''))) {
      errors.firstName = 'First name cannot be empty';
    }
    if (validator.isEmpty(String(data.lastName || ''))) {
      errors.lastName = 'Last name cannot be empty';
    }
    if (validator.isEmpty(String(data.email || ''))) {
      errors.email = 'Email cannot be empty';
    } else if (!validator.isEmail(toLoginEmail(data.email))) {
      errors.email = 'Invalid email';
    }
    if (validator.isEmpty(String(data.gender || ''))) {
      errors.gender = 'Gender cannot be empty';
    }
    if (validator.isEmpty(String(data.dateOfBirth || ''))) {
      errors.dateOfBirth = 'Date of birth cannot be empty';
    } else if (moment(data.dateOfBirth) > moment().subtract(3, 'years')) {
      errors.dateOfBirth = 'Invalid date of birth, Minimum age should be 3';
    }
    if (validator.isEmpty(String(data.joiningDateTime || ''))) {
      errors.joiningDateTime = 'Joining date cannot be empty';
    } else if (data.dateOfBirth >= data.joiningDateTime) {
      errors.joiningDateTime = "Joining date shouldn't be less than or equal to the Date of birth";
    }
    if (validator.isEmpty(String(data.bloodGroup || ''))) {
      errors.bloodGroup = 'Blood group cannot be empty';
    } else if (String(data.bloodGroup).trim().length < 3 || String(data.bloodGroup).trim().length > 5) {
      // Backend limit (size 3-5), e.g. "O+ve" - surface it here instead of as a generic 400.
      errors.bloodGroup = 'Blood group must be 3 to 5 characters, e.g. O+ve';
    }
    if (validator.isEmpty(String(data.nationality || ''))) {
      errors.nationality = 'Nationality cannot be empty';
    }
    if (validator.isEmpty(String(data.motherTongue || ''))) {
      errors.motherTongue = 'Mother tongue cannot be empty';
    }
    return errors;
  };

  const { data, errors, loading } = stateVal;

  const thisData = (
    <Modal size="lg" isOpen={isModalOpen}>
      <form onSubmit={handleSubmit}>
        <ModalHeader>{data?.studentId ? 'UPDATE STUDENT' : 'ADD STUDENT'}</ModalHeader>
        <ModalBody>
          {errors.global && <div className="mt-10 ml-15 mr-15 pad-12 alert alert-danger">{errors.global}</div>}
          <div className="content">
            <div className="container-fluid">
              {!data?.studentId && (
                <Row>
                  <Col sm={6}>
                    <FormGroup>
                      <Label htmlFor="">Select {courseStatic.toLowerCase()}</Label>
                      <CustomSelect
                        noLabel={true}
                        name="courseId"
                        value={data?.courseId}
                        onChange={handleSelectChange}
                        options={courseArr}
                        applyLabelStyle={true}
                        disabled={data?.studentId}
                      />
                      {errors.courseId && <span className="err-msg">{errors.courseId}</span>}
                    </FormGroup>
                  </Col>
                  <Col sm={6}>
                    <FormGroup>
                      <Label htmlFor="">
                        Select guardian<sup> *</sup>
                      </Label>
                      <CustomSelect
                        noLabel={true}
                        value={data?.guardian?.guardianId}
                        onChange={(name, value) => {
                          handleSelectChange('guardian', value);
                        }}
                        options={guardianArr}
                        applyLabelStyle={true}
                        disabled={data?.studentId}
                      />
                      {errors.guardianId && <span className="err-msg">{errors.guardianId}</span>}
                    </FormGroup>
                  </Col>
                </Row>
              )}
              <Row>
                <Col sm={6}>
                  <FormGroup>
                    <Label htmlFor="">
                      First name<sup> *</sup>
                    </Label>
                    <Input
                      type="text"
                      name="firstName"
                      onChange={e => handleChange(e)}
                      value={data.firstName}
                      placeholder="Enter here..."
                      maxLength="50"
                    />
                    {errors.firstName && <span className="err-msg">{errors.firstName}</span>}
                  </FormGroup>
                  <FormGroup>
                    <Label htmlFor="">
                      Last name<sup> *</sup>
                    </Label>
                    <Input
                      type="text"
                      name="lastName"
                      onChange={e => handleChange(e)}
                      value={data.lastName}
                      placeholder="Enter here..."
                      maxLength="50"
                    />
                    {errors.lastName && <span className="err-msg">{errors.lastName}</span>}
                  </FormGroup>
                  <FormGroup>
                    <Label htmlFor="">
                      Username or Email<sup> *</sup>
                    </Label>
                    <Input
                      type="text"
                      name="email"
                      onChange={e => handleChange(e)}
                      value={data.email}
                      placeholder="Enter here..."
                      maxLength="50"
                    />
                    {errors.email && <span className="err-msg">{errors.email}</span>}
                  </FormGroup>
                  <FormGroup style={{ marginTop: 15, marginBottom: 20 }}>
                    <Label for="exampleCheckbox">Gender</Label>
                    <Row>
                      <Col sm={3}>
                        <CustomCheckbox
                          value={data.gender}
                          id="MALE"
                          name="gender"
                          label="Male"
                          onChange={handleCheckChange}
                          checked={data.gender === 'MALE'}
                        />
                      </Col>
                      <Col sm={3}>
                        <CustomCheckbox
                          value={data.gender}
                          id="FEMALE"
                          name="gender"
                          label="Female"
                          onChange={handleCheckChange}
                          checked={data.gender === 'FEMALE'}
                        />
                      </Col>
                    </Row>
                    {errors.gender && <span className="err-msg">{errors.gender}</span>}
                  </FormGroup>
                  <FormGroup className="customDatePickerWidth">
                    <Label htmlFor="">
                      Date of Birth<sup> *</sup>
                    </Label>
                    <br />
                    <DatePicker
                      className="form-control"
                      selected={data.dateOfBirth ? new Date(data.dateOfBirth) : null}
                      onChange={value => handleDateChange('dateOfBirth', value)}
                      dateFormat="dd/MM/yyyy"
                      showMonthDropdown
                      showYearDropdown
                      placeholderText="Select date..."
                      dropdownMode="select"
                      maxDate={new Date()}
                    />
                    {errors.dateOfBirth && <span className="err-msg">{errors.dateOfBirth}</span>}
                  </FormGroup>
                  <FormGroup>
                    <Label htmlFor="">
                      Category<sup> *</sup>
                    </Label>
                    <Input
                      type="text"
                      name="category"
                      onChange={e => handleChange(e)}
                      value={data.category}
                      placeholder="Enter here..."
                      maxLength="50"
                    />
                    {errors.category && <span className="err-msg">{errors.category}</span>}
                  </FormGroup>
                </Col>
                <Col sm={6}>
                  <FormGroup>
                    <Label htmlFor="">
                      Blood group<sup> *</sup>
                    </Label>
                    <Input
                      type="text"
                      name="bloodGroup"
                      onChange={e => handleChange(e)}
                      value={data.bloodGroup}
                      placeholder="Enter here..."
                      maxLength="50"
                    />
                    {errors.bloodGroup && <span className="err-msg">{errors.bloodGroup}</span>}
                  </FormGroup>
                  <FormGroup className="customDatePickerWidth">
                    <Label htmlFor="">
                      Joining date<sup> *</sup>
                    </Label>
                    <br />
                    <DatePicker
                      className="form-control"
                      selected={data.joiningDateTime ? new Date(data.joiningDateTime) : null}
                      onChange={value => handleDateChange('joiningDateTime', value)}
                      dateFormat="dd/MM/yyyy"
                      showMonthDropdown
                      showYearDropdown
                      placeholderText="Select date..."
                      dropdownMode="select"
                      maxDate={new Date()}
                    />
                    {errors.joiningDateTime && <span className="err-msg">{errors.joiningDateTime}</span>}
                  </FormGroup>
                  <FormGroup>
                    <Label htmlFor="">
                      Nationality<sup> *</sup>
                    </Label>
                    <Input
                      type="text"
                      name="nationality"
                      onChange={handleChange}
                      value={data.nationality}
                      placeholder="Enter here..."
                      maxLength="50"
                    />
                    {errors.nationality && <span className="err-msg">{errors.nationality}</span>}
                  </FormGroup>
                  <FormGroup>
                    <Label htmlFor="">
                      Select Mother Tongue or Native Language<sup> *</sup>
                    </Label>
                    <Select
                      value={data.motherTongue ? languages.find(dt => dt.value === data.motherTongue) : null}
                      onChange={el => handleSelectLanguageChange('motherTongue', el.value)}
                      options={languages}
                    />
                    {errors.motherTongue && <span className="err-msg">{errors.motherTongue}</span>}
                  </FormGroup>
                  <FormGroup>
                    <Label htmlFor="">Birth place</Label>
                    <Input
                      type="text"
                      name="birthPlace"
                      onChange={e => handleChange(e)}
                      value={data.birthPlace}
                      placeholder="Enter here..."
                      maxLength="50"
                    />
                  </FormGroup>
                  <FormGroup style={{ marginTop: 15, marginBottom: 20 }}>
                    <Label for="exampleCheckbox">Staying in hostel</Label>
                    <Row>
                      <Col sm={3}>
                        <CustomCheckbox
                          id={`${true}`}
                          name="hostel"
                          label="Yes"
                          onChange={handleCheckChange}
                          checked={`${data.hostel}` === `${true}`}
                        />
                      </Col>
                      <Col sm={3}>
                        <CustomCheckbox
                          id={`${false}`}
                          name="hostel"
                          label="No"
                          onChange={handleCheckChange}
                          checked={`${data.hostel}` === `${false}`}
                        />
                      </Col>
                    </Row>
                  </FormGroup>
                </Col>
              </Row>
            </div>
          </div>
        </ModalBody>
        <ModalFooter>
          <CustomButton type="submit" disabled={loading} loading={loading} />
          <CustomButton
            className="ml-2"
            type="button"
            color="default"
            disabled={loading}
            onClick={formModalClose}
            name="Cancel"
          />
        </ModalFooter>
      </form>
    </Modal>
  );
  return <div>{thisData}</div>;
};

export default StudentFormModal;
