import React from 'react';
import { connect } from 'react-redux';
import { Row, Col } from 'reactstrap';
import { studentTableHead } from 'variables/general';
import StudentStatusTag from 'views/admin/Common/StudentStatusTag';
import { isFlaggedStudentStatus, flaggedStudentRowStyle } from 'utils/studentStatus';
import {
  fetchSchoolStudentsService,
  saveStudentService,
  fetchStudentService,
  updateStudentService,
  deleteStudentService,
  fetchCourseStudentsService,
  quickCreateStudentApi,
  fetchCourseStudentsListApi,
} from 'actions/admin/students';
import { fetchCurrentBatchByYearService } from 'actions/admin/batches.js';
import { fetchBatchCourseService, fetchEmployeeCoursesService } from 'actions/admin/courses.js';
import { fetchSchoolGuardiansService, fetchUnMappedGuardiansService } from 'actions/admin/guardians.js';
import { store } from 'index';
import { fetchReportService } from 'actions/admin/reports';
import StudentFormModal from './components/StudentFormModal.jsx';
import QuickStudentFormModal from './components/QuickStudentFormModal.jsx';
import constants, { courseStatic, formStudentName, regNoStatic } from '../../../config/constants.js';
import {
  formCourseSelectList,
  formResMessage,
  formUsernameFromEmail,
  getCurrentYearBatchUtils,
  getGlobalCurrentBatchUtils,
  getGlobalSchoolUtils,
  isWeb,
  makeSubstring,
  usernameTextColor,
} from '../../../utils/commonFunc.js';
import { showToast, setCommonParam } from '../../../actions/admin/auth.js';

import CustomButton from '../../../components/CustomButton.jsx';
import Radio from '@material-ui/core/Radio';
import colors from 'config/colors';
import moment from 'moment';
// import CollapseTable from '../Common/CollapseTable.jsx';
import CommonTooltip from '../Common/CommonTooltip.jsx';
import CustomInput from '../Common/CustomInput.jsx';
import MuiTable from '../Common/MuiTable.jsx';
import CommonSelect from 'components/CustomSelect';
import PeopleCountCards from '../Common/PeopleCountCards.jsx';

let searchTimer;
class StudentsPage extends React.Component {
  constructor(props) {
    super(props);
    this.state = {
      schoolId: 0,
      isModalOpen: false,
      pageParams: {
        page: 1,
        size: 10,
      },
      coursePageParams: {
        page: 1,
        size: 10,
      },
      // Remembers which of Batch/Class/My Class Students the admin last had selected, so
      // navigating away (e.g. into a student's profile) and back doesn't reset it.
      fetchStudentApiType: props.studentListApiType || 'schoolStudent',
      courseId: 0,
      isQuickStudentModalOpen: false,
      isQuickStudentSaving: false,
      isCollapseOpen: {},
      studentsFetching: false,
      courseStudentFetching: false,
      isStudentFetching: false,
      // Ful Info
      profileFetching: false,
      activitiesFetching: false,
      appreicationsFetching: false,
      homeworkFetching: false,
      assignmentsFetching: false,
      feeStructureFetching: false,
      searchParams: '',
      // Class view search: the class list is paged by the backend, so a search reads the class's whole list
      // once (courseAllStudents) and filters it here.
      courseSearch: '',
      courseAllStudents: null,
      courseSearchLoading: false,
      paymentsFetching: false,
    };
  }

  isLoading = (name, value) => this.setState({ [name]: value });

  fetchCurrentBatch = () => {
    const globalSchool = getGlobalSchoolUtils();
    const { startYear, endYear } = getCurrentYearBatchUtils();
    const { batchId } = getGlobalCurrentBatchUtils();
    if (!batchId && globalSchool?.schoolId) {
      store.dispatch(
        fetchCurrentBatchByYearService({
          token: this.props.loggedUserToken,
          schoolId: globalSchool.schoolId,
          startYear,
          endYear,
        })
      );
    }
  };

  fetchSchoolStudents = async refetchAgain => {
    const { batchId } = getGlobalCurrentBatchUtils();
    if (this.state.schoolId && batchId && (!this.props.studentsData?.content?.length || refetchAgain)) {
      this.isLoading('studentsFetching', true);
      await this.props.fetchSchoolStudents({
        schoolId: this.state.schoolId,
        batchId,
        token: this.props.loggedUserToken,
        pageParams: this.state.pageParams,
        searchParams: this.state.searchParams,
      });
      this.isLoading('studentsFetching', false);
    }
  };

  fetchUnMappedGuardians = () => {
    if (this.state.schoolId)
      this.props.fetchUnMappedGuardians({
        schoolId: this.state.schoolId,
        token: this.props.loggedUserToken,
      });
  };

  fetchSchoolGuardians = () => {
    const { batchId } = getGlobalCurrentBatchUtils();
    if (this.state.schoolId && batchId && !this.props.guardians?.length) {
      this.props.fetchSchoolGuardians({ schoolId: this.state.schoolId, batchId, token: this.props.loggedUserToken });
    }
    this.fetchUnMappedGuardians();
  };

  fetchBatchCourse = async (passBatchId, action) => {
    // this.clearStoreStudents();
    const { batchId } = getGlobalCurrentBatchUtils();
    if (passBatchId || batchId) {
      const res = !this.props.batchCourses?.length
        ? await this.props.fetchBatchCourse({
            schoolId: this.state.schoolId,
            batchId: passBatchId || batchId,
            token: this.props.loggedUserToken,
          })
        : this.props.batchCourses;
      const courseId = res?.[0]?.courseId;
      if (
        courseId !== this.state.courseId &&
        this.state.fetchStudentApiType === 'courseStudent' &&
        action !== 'FORM_MODAL'
      ) {
        this.handleSelectChange({ value: courseId });
      }
    }
  };

  fetchMyCourses = () => {
    // this.clearStoreStudents();
    const { batchId } = getGlobalCurrentBatchUtils();
    if (batchId && !this.props.empCourses?.length) {
      return this.props
        .fetchMyCourses({
          employeeId: this.props.loggedUserId,
          batchId,
          token: this.props.loggedUserToken,
        })
        .then(res => {
          if (res?.length) {
            this.handleSelectChange({ value: res?.[0].courseId });
          }
        });
    }
  };

  componentDidMount() {
    const globalSchool = getGlobalSchoolUtils();
    if (globalSchool) {
      this.setState({ schoolId: globalSchool.schoolId }, () => {
        this.fetchBatchCourse();
        // Force a refetch here (not just when the cache is empty) - searchParams/pageParams are
        // local state, reset fresh on every mount, but studentsData in redux can still be holding
        // whatever an earlier visit's search filtered it down to. Without this, coming back to
        // this page after searching, viewing a student, then navigating back would show that
        // stale filtered list under an empty, unfiltered-looking search box.
        this.fetchSchoolStudents(true);
        this.fetchSchoolGuardians(); //modal
      });
    } else {
      this.showWarning('Please select School', 'warning');
    }

    const { batchId } = getGlobalCurrentBatchUtils();
    if (!batchId) {
      this.fetchCurrentBatch();
    }
  }

  formModalOpen = () => {
    this.setState({ isModalOpen: true });
  };

  formModalClose = () => {
    this.setState({ isModalOpen: false, isViewModalOpen: false });
  };

  quickStudentModalClose = () => this.setState({ isQuickStudentModalOpen: false });

  // From a class list the new student goes into the class picked in the filter above; from the batch list
  // the dialog asks for the class (pickedCourseId).
  saveQuickStudent = async (postData, pickedCourseId) => {
    const { batchId } = getGlobalCurrentBatchUtils();
    const courseId = pickedCourseId || this.state.courseId;
    if (!batchId || !courseId) {
      this.showWarning(`Select a ${courseStatic.toLowerCase()} first`, 'warning');
      return;
    }
    this.setState({ isQuickStudentSaving: true });
    try {
      await quickCreateStudentApi({
        postData: { ...postData, schoolId: this.state.schoolId },
        token: this.props.loggedUserToken,
        batchId,
        courseId,
      });
      this.setState({ isQuickStudentSaving: false, isQuickStudentModalOpen: false });
      this.showWarning('Student added successfully', 'success');
      // Both lists: the class list the admin is looking at, and the batch list (cached in redux).
      this.setState({ courseAllStudents: null });
      if (this.state.courseId) this.fetchCourseStudents(this.state.courseId, true);
      this.fetchSchoolStudents(true);
    } catch (err) {
      this.setState({ isQuickStudentSaving: false });
      this.showWarning(formResMessage(err), 'error');
    }
  };

  saveStudent = postData => {
    const { batchId } = getGlobalCurrentBatchUtils();
    postData.school = { schoolId: this.state.schoolId };
    return this.props.saveStudent({
      postData,
      token: this.props.loggedUserToken,
      batchId,
      courseId: postData?.courseId,
    });
  };

  fetchStudent = studentId => {
    const { batchId } = getGlobalCurrentBatchUtils();
    return this.props.fetchStudent({ studentId, token: this.props.loggedUserToken, batchId }).then(() => {
      this.formModalOpen();
    });
  };

  updateStudent = data => {
    data.school = { schoolId: this.state.schoolId };
    return this.props.updateStudent({
      studentId: data.studentId,
      postData: data,
      token: this.props.loggedUserToken,
    });
  };

  studentUpdateSuccess = actionParam => {
    this.setState({ isModalOpen: false });
    this.showWarning(actionParam === 'add' ? 'Student added successfully' : 'Student Updated successfully', 'success');
    this.fetchSchoolStudents(true);
    // The class list is a separate cached list - refresh it too when editing from there.
    if (this.state.courseId && this.state.fetchStudentApiType !== 'schoolStudent') {
      this.fetchCourseStudents(this.state.courseId, true);
    }
  };

  showWarning = (message, type) => {
    store.dispatch(showToast(message, type));
  };

  deleteStudent = studentId => {
    return this.props
      .deleteStudent({ studentId, token: this.props.loggedUserToken })
      .then(() => {
        this.fetchSchoolStudents(true);
      })
      .catch(err => {
        this.showWarning(formResMessage(err), 'error');
      });
  };

  clearStoreStudents = () => {
    // store.dispatch(getAllStudents({ content: [] }));
    // store.dispatch(getCourseStudents({ content: [] }));
  };

  fetchCourseStudents = async (courseId, refetchAgain) => {
    // this.clearStoreStudents();
    const { batchId } = getGlobalCurrentBatchUtils();
    this.setState(prevState => ({ ...prevState, courseId }));
    if (courseId && (!this.props.courseStudentData?.content?.length || refetchAgain)) {
      this.isLoading('courseStudentFetching', true);
      await this.props.fetchCourseStudents({
        courseId,
        token: this.props.loggedUserToken,
        pageParams: this.state.coursePageParams,
        batchId,
      });
      this.isLoading('courseStudentFetching', false);
    }
  };

  viewStudentReport = (studentId, apiName = 'generateSimplePDFReport') => {
    this.props.fetchStudentReport({
      apiName,
      studentId,
      token: this.props.loggedUserToken,
    });
  };

  fetchPageData = page => {
    if (page !== this.state.pageParams.page) {
      const name = this.state.fetchStudentApiType === 'schoolStudent' ? 'pageParams' : 'coursePageParams';
      const existPageParams = this.state[name];
      this.setState(
        {
          [name]: {
            ...existPageParams,
            page,
          },
        },
        () => {
          if (this.state.fetchStudentApiType === 'schoolStudent') {
            this.fetchSchoolStudents(true);
          } else {
            this.fetchCourseStudents(this.state.courseId, true);
          }
        }
      );
    }
  };

  fetchStudentApiType = fetchStudentApiType => {
    this.setState(prevState => ({
      ...prevState,
      fetchStudentApiType,
      pageParams: {
        page: 1,
        size: 10,
      },
    }));
  };

  fetchActivePageData = () => {
    const val = this.state.fetchStudentApiType;
    if (val === 'schoolStudent') {
      this.fetchSchoolStudents();
    } else if (val === 'courseStudent') {
      this.fetchBatchCourse();
    } else if (val === 'myStudent') {
      this.fetchMyCourses();
    }
  };

  handleCheckChange = val => {
    setCommonParam('studentListApiType', val);
    this.setState(
      {
        ...this.state,
        fetchStudentApiType: val,
        courseSearch: '',
      },
      () => {
        this.fetchActivePageData();
      }
    );
  };

  handleSelectChange = selectItem => {
    this.setState(
      {
        ...this.state,
        courseId: selectItem.value,
        courseSearch: '',
        // pageParams: {
        //   ...this.state.pageParams,
        //   page: 1,
        // },
        coursePageParams: {
          ...this.state.coursePageParams,
          page: 1,
        },
      },
      () => {
        this.fetchCourseStudents(selectItem?.value, true);
      }
    );
  };

  showGuardianInfo = (studentId, isOpen) => {
    this.setState({
      isCollapseOpen: {
        [studentId]: isOpen,
      },
    });
  };

  viewStudent = studentId => {
    this.props.history.push(`/admin/students/${studentId}/view`);
  };

  handleCourseSearchChange = async (name, value) => {
    this.setState({ courseSearch: value });
    const { batchId } = getGlobalCurrentBatchUtils();
    const { courseId, courseAllStudents } = this.state;
    if (!value.trim() || !courseId || courseAllStudents?.courseId === courseId) return;
    this.setState({ courseSearchLoading: true });
    try {
      const res = await fetchCourseStudentsListApi({ courseId, batchId, token: this.props.loggedUserToken });
      this.setState({ courseAllStudents: { courseId, list: res.data || [] } });
    } catch (err) {
      this.showWarning(formResMessage(err), 'error');
    }
    this.setState({ courseSearchLoading: false });
  };

  handleSearchChange = (name, value) => {
    clearTimeout(searchTimer);
    this.setState(
      {
        ...this.state,
        searchParams: value,
        pageParams: {
          page: value ? 1 : this.state.pageParams.page,
          size: value ? 10 : this.state.pageParams.size,
        },
      },
      () => {
        searchTimer = setTimeout(() => {
          this.fetchSchoolStudents(true);
        }, 500);
      }
    );
  };

  render() {
    const {
      isModalOpen,
      fetchStudentApiType,
      courseId,
      isCollapseOpen,
      studentsFetching,
      courseStudentFetching,
      searchParams,
      courseSearch,
      courseAllStudents,
      courseSearchLoading,
    } = this.state;
    const isCourseView = ['courseStudent', 'myStudent'].includes(fetchStudentApiType);
    // const batchData = getGlobalCurrentBatchUtils();
    const {
      // API: /api/admin/get-school-student-by-batch/${data.schoolId}/${data.batchId}?page=1&size=10
      // Or Filter: /api/admin/get-school-student-by-filter/${data.schoolId}?page=1&size=10
      studentsData,
      student,
      batches,
      batchCourses,
      guardians,
      loggedUserRole,
      empCourses,
      courseStudentData,
      // currentBatch = batchData,
      unMappedGuardianList,
    } = this.props;

    // Choice cards instead of a bare radio + hover-only info icon: the description sits right
    // under the label so it's readable at a glance (and on touch devices) instead of needing a
    // hover, and it sidesteps the old icon's absolute-position offset drifting out of place.
    const choiceCard = (checked, label, description, onClick) => (
      <div
        onClick={onClick}
        style={{
          display: 'flex',
          alignItems: 'flex-start',
          gap: 4,
          padding: '8px 12px',
          borderRadius: 8,
          border: `1.5px solid ${checked ? colors.accent : '#e0e0e0'}`,
          backgroundColor: checked ? '#F5EDFB' : '#fff',
          cursor: 'pointer',
        }}>
        <Radio checked={checked} size="small" style={{ color: colors.accent, padding: 2, marginTop: -2 }} />
        <div>
          <div style={{ fontWeight: 'bold', fontSize: 13 }}>{label}</div>
          <div style={{ fontSize: 12, color: '#6b778a', marginTop: 2 }}>{description}</div>
        </div>
      </div>
    );

    const courseFilter = () => {
      return (
        <Row>
          <Col md={6} className="mb-2">
            {choiceCard(
              fetchStudentApiType === 'schoolStudent',
              'BATCH STUDENTS',
              'School students for a specific batch',
              () => this.handleCheckChange('schoolStudent')
            )}
          </Col>
          <Col md={6} className="mb-2">
            {loggedUserRole === constants.roles.SA || loggedUserRole === constants.roles.admin
              ? choiceCard(
                  fetchStudentApiType === 'courseStudent',
                  `${courseStatic.toUpperCase()} STUDENTS`,
                  `${courseStatic} students for a selected ${courseStatic.toLowerCase()}`,
                  () => this.handleCheckChange('courseStudent')
                )
              : loggedUserRole === constants.roles.teacher
              ? choiceCard(
                  fetchStudentApiType === 'myStudent',
                  `MY ${courseStatic.toUpperCase()} STUDENTS`,
                  `${courseStatic} students for a selected ${courseStatic.toLowerCase()}`,
                  () => this.handleCheckChange('myStudent')
                )
              : null}
          </Col>
        </Row>
      );
    };

    const courseArr = formCourseSelectList(fetchStudentApiType === 'myStudent' ? empCourses : batchCourses);

    const filterSelect = () => {
      if (['courseStudent', 'myStudent'].includes(fetchStudentApiType)) {
        return (
          <Row>
            <Col sm={6} md={6} lg={6} className="mb-2">
              <CommonSelect
                name="courseId"
                noLabel={true}
                value={courseId}
                onChange={(name, value) => {
                  this.handleSelectChange({ value });
                }}
                options={courseArr}
                applyLabelStyle={true}
                placeholder={`Select ${courseStatic}`}
              />
            </Col>
            <Col sm={6} md={6} lg={6} className="mb-2">
              <CustomInput
                name="courseSearch"
                onChange={this.handleCourseSearchChange}
                placeholder={`Search by name, ${regNoStatic.toLowerCase()}...`}
                value={courseSearch}
              />
            </Col>
          </Row>
        );
      }
      return null;
    };

    const students = {
      schoolStudent: studentsData, // Batch students
      courseStudent: courseStudentData,
      myStudent: courseStudentData,
    };
    const courseNeedle = courseSearch.trim().toLowerCase();
    const searchingCourse = isCourseView && !!courseNeedle && courseAllStudents?.courseId === courseId;
    const filterStudents = () => {
      const sList = searchingCourse
        ? {
            content: courseAllStudents.list.filter(
              el =>
                formStudentName(el).toLowerCase().includes(courseNeedle) ||
                `${el.registerNumber || ''}`.toLowerCase().includes(courseNeedle) ||
                `${el.email || ''}`.toLowerCase().includes(courseNeedle)
            ),
          }
        : students?.[fetchStudentApiType] || {};
      return {
        ...sList,
        content: sList?.content?.map(el => ({
          ...el,
          registerNumber: (
            <span>
              <CommonTooltip content={el.registerNumber}>
                <span>{makeSubstring(el.registerNumber, isWeb ? 20 : 10)}</span>
              </CommonTooltip>{' '}
              {el.email && (
                <CommonTooltip content={el.email}>
                  <span style={{ color: usernameTextColor }}>
                    ({makeSubstring(formUsernameFromEmail(el.email), isWeb ? 20 : 10)})
                  </span>
                </CommonTooltip>
              )}
            </span>
          ),
          studentName: (
            <span>
              {formStudentName(el)}
              {isFlaggedStudentStatus(el.status) && (
                <div className="mt-1">
                  <StudentStatusTag status={el.status} />
                </div>
              )}
            </span>
          ),
          //courseName: el.courses[0]?.name,
          // gender: el.gender,
          // moment(undefined) is "now" - quick-added students have no DOB yet, so don't show today's date.
          dob: el.dateOfBirth ? moment(el.dateOfBirth).format('DD MMM, YYYY') : '--',
          guardianName: (
            <span>
              <div>{el?.guardName}</div>
              {el.guardEmail && (
                <CommonTooltip content={el.guardEmail}>
                  <div style={{ color: usernameTextColor }}>
                    {makeSubstring(formUsernameFromEmail(el.guardEmail), isWeb ? 20 : 10)}
                  </div>
                </CommonTooltip>
              )}
            </span>
          ),
        })),
      };
    };
    const studentListData = filterStudents();
    const getCourseAndBatch = id => {
      const studentItem = studentListData.content?.find(el => el.studentId === id);
      return { batchId: studentItem?.currentBatch?.batchId, courseId: studentItem?.currentCourse?.courseId };
    };

    return (
      <div className="content">
        <Row>
          <Col md={6}>{courseFilter()}</Col>
          <Col md={6}>
            <CustomButton
              style={{ float: 'right', backgroundColor: colors.accent, color: colors.white, whiteSpace: 'nowrap' }}
              onClick={() => this.setState({ isQuickStudentModalOpen: true })}
              disabled={fetchStudentApiType !== 'schoolStudent' && !courseId}
              name="+ Quick Add Student"
            />
          </Col>
        </Row>
        {filterSelect()}
        <PeopleCountCards
          show={isCourseView ? ['students', 'classStudents', 'classEmployees'] : ['students']}
          courseId={isCourseView ? courseId : null}
          refreshKey={
            studentListData.page?.totalElements ?? studentListData.totalElements ?? studentListData.content?.length
          }
          style={{ marginTop: 10 }}
        />
        {!isCourseView && (
          <div style={{ maxWidth: 320, marginTop: 4 }}>
            <CustomInput
              name="searchParams"
              onChange={this.handleSearchChange}
              placeholder={`Search by name, ${regNoStatic.toLowerCase()}, username...`}
              value={searchParams}
            />
          </div>
        )}
        <MuiTable
          // enableSearch={true}
          // searchFields={[
          //   { order: 1, label: 'studentName' },
          //   { order: 2, label: 'registerNumber' },
          //   { order: 3, label: 'email' },
          // ]}
          // handleSearchChange={this.handleSearchChange}
          tableHeaders={studentTableHead}
          tableBodyData={studentListData}
          bodyColumns={['studentName', 'registerNumber', 'dob', 'guardianName', 'action']}
          dropDownActions={['edit', 'student_report', 'student_task_assignment']}
          renderRowExtra={item => (
            <CustomButton
              variant="outlined"
              color="default"
              size="small"
              name="View"
              onClick={() => this.viewStudent(item.studentId)}
            />
          )}
          idName="studentId"
          getRowStyle={item => flaggedStudentRowStyle(item?.status)}
          fetchItem={this.fetchStudent}
          deleteItem={this.deleteStudent}
          fetchPageData={this.fetchPageData}
          fetchViewData={this.showGuardianInfo}
          collapseViewHeading="Guardian"
          collapseViewHeaders={[
            'guardName',
            'guardEmail',
            'guardianMobile',
            'relation',
            'guardianEducation',
            'guardianOccupation',
          ]}
          collapseViewColumns={['Name', 'Email', 'Mobile', 'Relation', 'Education', 'Occupation']}
          isCollapseOpen={isCollapseOpen}
          // isLoading={studentsFetching}
          isLoading={
            (fetchStudentApiType === 'schoolStudent' && studentsFetching) ||
            (fetchStudentApiType === 'courseStudent' && courseStudentFetching) ||
            courseSearchLoading
          }
          // showViewOnHover={true}
          viewStudentReport={this.viewStudentReport}
          viewItem={this.viewStudent}
          viewStudentTaskAssignmentReport={id => this.viewStudentReport(id, 'generateHomeworkPDFReport')}
          viewStudentProgressReport={id =>
            this.viewStudentReport(id, 'generateStudentProgressPDFReport', getCourseAndBatch(id))
          }
        />
        <StudentFormModal
          isModalOpen={isModalOpen}
          formModalCloseProp={this.formModalClose}
          batches={batches}
          batchCourses={batchCourses}
          fetchBatchCourse={this.fetchBatchCourse}
          // fetchSchoolGuardians={this.fetchSchoolGuardians}
          guardians={guardians}
          saveStudent={this.saveStudent}
          student={student}
          updateStudent={this.updateStudent}
          studentUpdateSuccess={this.studentUpdateSuccess}
          scrollToTop={() => window.scrollTo(0, 0)}
          unMappedGuardianList={unMappedGuardianList}
        />

        <QuickStudentFormModal
          isOpen={this.state.isQuickStudentModalOpen}
          className={courseArr?.find(el => el.value === courseId)?.label}
          askCourse={fetchStudentApiType === 'schoolStudent'}
          courseOptions={courseArr}
          saving={this.state.isQuickStudentSaving}
          onClose={this.quickStudentModalClose}
          onSave={this.saveQuickStudent}
        />
      </div>
    );
  }
}

const mapStateToProps = state => {
  return {
    loggedUserId: state.auth.loggedUserId,
    loggedUserToken: state.auth.loggedUserToken,
    loggedUserRole: state.auth.loggedUserRole,
    loggedUserSchool: state.auth.loggedUserSchool,
    studentListApiType: state.auth.studentListApiType,
    batches: state.batches.batchList,
    batchCourses: state.courses.batchCourseList,
    guardians: state.guardians.guardianList,
    srchSelectList: state.students.srchSelectList,
    studentsData: state.students.studentsData,
    courseStudentData: state.students.courseStudentData,
    student: state.students.student,
    empCourses: state.courses.empCourseList,
    currentBatch: state.batches.currentBatch?.batchId ? state.batches.currentBatch : undefined,
    unMappedGuardianList: state.guardians.unMappedGuardianList,
    // schoolBatchCourseList: state?.courses?.schoolBatchCourseList,
  };
};

const mapDispatchToProps = dispatch => {
  return {
    fetchSchoolStudents: data => dispatch(fetchSchoolStudentsService(data)),
    fetchSchoolGuardians: data => dispatch(fetchSchoolGuardiansService(data)),
    saveStudent: data => dispatch(saveStudentService(data)),
    fetchStudent: data => dispatch(fetchStudentService(data)),
    updateStudent: data => dispatch(updateStudentService(data)),
    deleteStudent: data => dispatch(deleteStudentService(data)),
    // Same API's
    fetchBatchCourse: data => dispatch(fetchBatchCourseService(data)),
    //============//
    fetchMyCourses: data => dispatch(fetchEmployeeCoursesService(data)),
    fetchCourseStudents: data => dispatch(fetchCourseStudentsService(data)),
    // Report
    fetchStudentReport: data => dispatch(fetchReportService(data)),
    // Search Api
    // fetchStudentsByCourse: (data) => dispatch(fetchStudentsByCourseService(data)),
    // fetchStudentsByBatch: (data) => dispatch(fetchStudentsByBatchService(data)),
    fetchUnMappedGuardians: data => dispatch(fetchUnMappedGuardiansService(data)),
  };
};

export default connect(mapStateToProps, mapDispatchToProps)(StudentsPage);
