// A student's `status` is normally ACTIVE. These are the statuses the backend uses for a student who has left, is leaving or needs
// attention: wherever students are listed they are labelled and highlighted so they stand out among the rest.
export const STUDENT_STATUS_LABELS = {
  TC_ISSUED: 'Transfer Certificate Issued',
  TRANSFERRED: 'Transferred to Another School',
  DISCONTINUED: 'Discontinued Studies',
  DROPPED_OUT: 'Dropped Out',
  GRADUATED: 'Graduated',
  ALUMNI: 'Alumni',
  EXPELLED: 'Expelled from School',
  LONG_ABSENCE: 'Long-Term Absence',
  DISCIPLINARY_ACTION: 'Disciplinary Action',
  COMPLETED_SCHOOLING: 'Completed Schooling',
  OTHER: 'Other',
};

// red: left on bad terms / needs action, amber: left or away, green: finished well
const RED = '#c62828';
const AMBER = '#b26a00';
const GREEN = '#2e7d32';
const STUDENT_STATUS_COLORS = {
  EXPELLED: RED,
  DISCIPLINARY_ACTION: RED,
  DROPPED_OUT: RED,
  DISCONTINUED: RED,
  TC_ISSUED: AMBER,
  TRANSFERRED: AMBER,
  LONG_ABSENCE: AMBER,
  OTHER: AMBER,
  GRADUATED: GREEN,
  ALUMNI: GREEN,
  COMPLETED_SCHOOLING: GREEN,
};

export const isFlaggedStudentStatus = status => !!STUDENT_STATUS_LABELS[status];

export const studentStatusLabel = status => STUDENT_STATUS_LABELS[status] || '';

export const studentStatusColor = status => STUDENT_STATUS_COLORS[status] || AMBER;

// A light tint of the status colour for the whole row, plus a coloured edge, so a flagged student stands out in a table of ten.
export const flaggedStudentRowStyle = status =>
  isFlaggedStudentStatus(status)
    ? { backgroundColor: `${studentStatusColor(status)}12`, boxShadow: `inset 4px 0 0 ${studentStatusColor(status)}` }
    : undefined;
